    // Initialize a 2D array to store the number of ways to distribute M apples into N plates
    $dp = array_fill(0, $M + 1, array_fill(0, $N + 1, 0));

    // There is one way to distribute 0 apples into any number of plates
    for ($i = 0; $i <= $N; $i++) {
        $dp[0][$i] = 1;
    }

    // Fill the dp array
    for ($i = 1; $i <= $M; $i++) {
        for ($j = 1; $j <= $N; $j++) {
            // If the number of apples is less than the number of plates,
            // the number of ways is the same as the number of ways to distribute i apples into j - 1 plates
            if ($i < $j) {
                $dp[$i][$j] = $dp[$i][$j - 1];
            } else {
                // Otherwise, the number of ways is the sum of the number of ways to distribute i apples into j - 1 plates
                // and the number of ways to distribute i - j apples into j plates
                $dp[$i][$j] = $dp[$i][$j - 1] + $dp[$i - $j][$j];
            }
        }
    }

    // The number of ways to distribute M apples into N plates is stored in dp[M][N]
    return $dp[$M][$N];
}

